// One place that turns the Slack reply into (1) the text sent to LINE and (2) the learn decision.
const row = $input.first().json;
const msg = $('Slack message').first().json;
const text = String(msg.text ?? '');
// Learning is opt-in: only a reply that contains #learn is learned. The tag itself is never sent to the customer.
const TAG = /(^|\s)#learn\b/gi;
const learn_requested = /(^|\s)#learn\b/i.test(text);
const send_text = text.replace(TAG, '').trim();
if (!send_text) return [];
// The customer may have written several messages since the last staff reply. Keep them all: the AI later picks the one this reply answers.
let inquiries = [];
try { inquiries = JSON.parse(row.pending_inquiries || '[]'); } catch (e) { inquiries = []; }
if (!inquiries.length && row.last_inquiry) inquiries = [row.last_inquiry];
return [{ json: {
  line_user_id: row.line_user_id,
  customer_name: row.customer_name ?? '',
  inquiries,
  send_text,
  learn_requested,
  thread_ts: msg.thread_ts,
  reply_ts: msg.ts,
  staff: msg.user ?? ''
} }];

function maskPII(text, known) {
  let s = String(text ?? '');
  const hits = {};
  const rep = (re, label) => { s = s.replace(re, () => { hits[label] = (hits[label] || 0) + 1; return '[' + label + ']'; }); };
  for (const [v, label] of known) { if (v && v.length >= 2 && s.includes(v)) { hits[label] = (hits[label] || 0) + 1; s = s.split(v).join('[' + label + ']'); } }
  rep(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, 'EMAIL');
  rep(/\b\d(?:[ -]?\d){12,15}\b/g, 'CARD');
  rep(/(?<!\d)\(?\d{3}\)?[-.\s]\d{3}[-.\s]\d{4}(?!\d)/g, 'PHONE');
  rep(/\+\d{1,3}[-\s]?\(?\d{1,4}\)?[-\s]?\d{2,4}[-\s]?\d{3,4}\b/g, 'PHONE');
  rep(/(?<![\d-])〒?\s?\d{3}-\d{4}(?![\d-])/g, 'POSTAL');
  rep(/(?:\+81[-\s]?|\b0)\d{1,4}[-\s]?\d{1,4}[-\s]?\d{3,4}\b/g, 'PHONE');
  rep(/(?<=(?:注文|受付|会員|契約|お客様|order|account|member|contract|customer|reservation)\s?(?:番号|No\.?|ID|number|#)(?:\s?(?:is|was|are|は|が))?[:：\s#]*)[A-Za-z0-9-]{5,}/gi, 'ID');
  return { text: s, hits };
}
// The shop's own phone numbers and emails (Learning settings > keep_contacts) are not personal data of a customer.
// They are hidden from the masking while it runs and put back afterwards. Matching is exact text, ignoring case.
function maskKeep(text, known, keep) {
  let s = String(text ?? '');
  const slots = [];
  for (const v of keep) {
    const re = new RegExp(v.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'gi');
    s = s.replace(re, (m) => { slots.push(m); return '\u0001' + (slots.length - 1) + '\u0001'; });
  }
  const r = maskPII(s, known);
  r.text = r.text.replace(/\u0001(\d+)\u0001/g, (_, i) => slots[Number(i)]);
  return r;
}

const base = $('Prepare reply').first().json;
const keep = String($('Learning settings').first().json.keep_contacts || '').split(/[,\n]/).map(x => x.trim()).filter(Boolean);
const name = String(base.customer_name || '').trim();
const known = [[name, 'NAME'], ...name.split(/[\s　]+/).map(p => [p, 'NAME'])];
const cands = base.inquiries.map(t => maskKeep(t, known, keep));
const a = maskKeep(base.send_text, known, keep);
const case_id = base.thread_ts + '-' + base.reply_ts;
return [{ json: {
  ...base,
  case_id,
  cands_rx: cands.map(c => c.text),
  question_rx: cands.map((c, i) => (i + 1) + '. ' + c.text).join('\n'),
  answer_rx: a.text,
  keep_text: keep.length ? keep.join(', ') : '(none)',
  keep_list: keep,
  pre_reject: cands.length ? '' : 'No inquiry text is saved for this thread',
  pii_hits: { question: cands.map(c => c.hits), answer: a.hits }
} }];

