const base = $('Mask with regex').first().json;
let q = '', a = '', idx = 0, reason = base.pre_reject || '';
if (!reason) {
  try {
    const rawText = $json.content?.[0]?.text ?? $json.text;
    // Claude has no JSON mode, so it may wrap the JSON in a code fence. Strip it before parsing.
    const t = String(rawText ?? '').replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
    const o = JSON.parse(t);
    idx = Number(o.question_index);
    q = String(o.question ?? '');
    a = String(o.answer ?? '');
  } catch (e) { reason = 'The AI output could not be read as JSON'; }
}
if (!reason) {
  if (!Number.isInteger(idx) || idx < 1 || idx > base.cands_rx.length) reason = 'The reply does not clearly answer one of the saved customer messages';
  else if (!q.trim() || !a.trim()) reason = 'The AI output is empty';
  else if (q.length < base.cands_rx[idx - 1].length * 0.5 || a.length < base.answer_rx.length * 0.5) reason = 'The AI output is much shorter than the input (possible summary or loss)';
  else {
    const r = maskKeep(q + '\n' + a, [], base.keep_list);
    const left = Object.keys(r.hits);
    if (left.length) reason = 'Personal data patterns remain after masking: ' + left.join(',');
  }
}
return [{ json: { ...base, learn_ok: !reason, mask_note: reason, question_masked: q, answer_masked: a } }];

