const threads = $('Get threads waiting for a reply').all().map(i => i.json);
const settings = $('Reminder settings').first().json;
// An empty table returns one empty item, so keep only real records
const records = new Map($input.all().map(i => i.json).filter(r => r.slack_ts).map(r => [r.slack_ts, r]));

return threads.map(thread => {
  const record = records.get(thread.slack_ts) ?? {};
  // The thread row's updatedAt is the time of the customer's latest message.
  const lastActivity = DateTime.fromISO(thread.updatedAt);
  const lastReminded = record.last_reminded_at ? DateTime.fromISO(record.last_reminded_at) : null;
  // If the customer wrote again after our last reminder, start counting from zero.
  const isNewWait = !lastReminded || lastReminded < lastActivity;
  const remindersSent = isNewWait ? 0 : Number(record.reminder_count ?? 0);
  const waitingSince = isNewWait ? lastActivity : lastReminded;
  const minutesSinceLastNudge = Math.floor($now.diff(waitingSince, 'minutes').minutes);
  const minutesWaiting = Math.floor($now.diff(lastActivity, 'minutes').minutes);
  return { json: {
    slack_ts: thread.slack_ts,
    last_inquiry: thread.last_inquiry,
    minutes_waiting: minutesWaiting,
    reminder_number: remindersSent + 1,
    max_reminders: settings.max_reminders,
    due: minutesSinceLastNudge >= settings.wait_minutes && remindersSent < settings.max_reminders,
  } };
});
